import{_ as a,c as t,a5 as o,o as l}from"./chunks/framework.mFcBg5UA.js";const i="/my-blog/question/javascript/carbage_recovery_mechanism.jpg",b=JSON.parse('{"title":"JS垃圾回收机制","titleTemplate":"前端面试题","description":"","frontmatter":{"outline":"deep","title":"JS垃圾回收机制","titleTemplate":"前端面试题","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/question/javascript/carbage_recovery_mechanism.html"}]]},"headers":[],"relativePath":"question/javascript/carbage_recovery_mechanism.md","filePath":"question/javascript/carbage_recovery_mechanism.md","lastUpdated":1724510899000}'),e={name:"question/javascript/carbage_recovery_mechanism.md"};function n(s,r,g,c,h,p){return l(),t("div",null,r[0]||(r[0]=[o('<h1 id="js垃圾回收机制" tabindex="-1">JS垃圾回收机制 <a class="header-anchor" href="#js垃圾回收机制" aria-label="Permalink to &quot;JS垃圾回收机制&quot;">​</a></h1><img src="'+i+'" width="500" height="520"><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><h3 id="gc" tabindex="-1">GC <a class="header-anchor" href="#gc" aria-label="Permalink to &quot;GC&quot;">​</a></h3><p>在 JavaScript 中，GC 代表&quot;垃圾回收&quot;（Garbage Collection）。垃圾回收是一种自动内存管理机制，负责监测不再使用的对象，并释放它们占用的内存空间，以避免内存泄漏和资源浪费。<br>JavaScript 是一种高级编程语言，它在运行时动态地创建和销毁对象。当创建对象时，JavaScript 引擎会为其分配内存空间，而当对象不再被引用或使用时，内存空间应该被释放以便在后续的代码执行中重新利用。垃圾回收机制就是负责自动检测和清除不再需要的对象，以释放占用的内存。<br><strong>用通俗的例子来解释的话就是:</strong><br>假设内存空间是一间房间,里面满满当当都堆着各种各样的东西。这时候你想在房间里面再放新的东西,就要先把一些不要的旧东西清理出去。<br>JS 引擎就像个管家,它会定期查看房间里哪些东西不再被使用或者无法访问到了。这些被遗忘的旧物品就像是内存中的“垃圾”,会被 GC 收集起来扔出房间。扔出这些垃圾后,房间就空出空间来了,可以继续用来存放新的变量、对象等程序的数据了。<br>GC 就好比是程序的内存管家,不断地检查内存使用情况,发现那些可以被清理的垃圾,然后自动回收这些内存。这对保证 JS 程序平滑运行非常重要。</p><h3 id="垃圾产生原因" tabindex="-1">垃圾产生原因 <a class="header-anchor" href="#垃圾产生原因" aria-label="Permalink to &quot;垃圾产生原因&quot;">​</a></h3><ol><li><strong>内存分配时产生：</strong> JS 程序在运行过程中,会不断地申请内存来存储对象、变量等数据。这些内存使用完后就成了“垃圾”。</li><li><strong>不再被引用：</strong> 由于 JS 是动态语言,一个对象是否还被使用,只能通过是否有引用来判断。如果对象没有被任何东西引用,它就成为了垃圾。</li><li><strong>全局变量、循环引用：</strong> 全局变量、闭包、循环引用等情况会导致某些内存无法被释放,这部分内存也会变成垃圾。</li><li><strong>程序运行产生的中间状态：</strong> 像函数的局部变量等 temporal 数据也会占用内存,使用完就成为垃圾</li></ol><h3 id="为什么要回收垃圾" tabindex="-1">为什么要回收垃圾 <a class="header-anchor" href="#为什么要回收垃圾" aria-label="Permalink to &quot;为什么要回收垃圾&quot;">​</a></h3><ol><li><strong>管理内存使用：</strong> JS 中内存的分配和释放都是自动的,为了控制内存占用,需要有垃圾回收机制来回收未使用的内存。</li><li><strong>防止内存泄漏：</strong> 由于对象之间相互引用,可能导致一些未被使用的对象无法释放,垃圾回收可以找到并释放这些对象。</li><li><strong>释放内存：</strong> 定期回收不再需要的对象内存,释放内存空间让程序重新使用。</li><li><strong>提高性能：</strong> 释放未使用的内存可以使得内存使用更高效,减少内存碎片,提高程序性能。</li><li><strong>优化内存：</strong> 垃圾回收可以按照使用情况优化内存的分配,减少内存占用。</li><li><strong>简化开发：</strong> 开发者不需要关注内存控制,垃圾回收自动完成内存管理的工作。</li><li><strong>避免常见错误：</strong> 自动内存管理可以防止手动内存控制常见的错误,例如内存泄漏、访问未分配内存等</li></ol><h2 id="几种机制" tabindex="-1">几种机制 <a class="header-anchor" href="#几种机制" aria-label="Permalink to &quot;几种机制&quot;">​</a></h2><h3 id="引用计数" tabindex="-1">引用计数 <a class="header-anchor" href="#引用计数" aria-label="Permalink to &quot;引用计数&quot;">​</a></h3><p>引用计数(Reference Counting)是 JS 中较早的垃圾回收方式之一。<br><strong>✴️ 基本思想：</strong><br>追踪记录每个对象被引用的次数,当一个对象的引用数达到 0 的时候,说明这个对象不再被使用,那么就可以将其占用的内存空间回收释放。每个对象有一个引用计数属性,初始值为 0 ==&gt; 当对象被引用时,其计数器加 1 ==&gt; 当引用失效时,计数器减 1 ==&gt; 当计数器为 0 时,表示对象不再需要,该对象的内存空间可以被回收。<br><strong>✅ 优点:</strong></p><ol><li>实现简单,资源消耗较少</li><li>可以立即回收内存,不需要等到执行周期结束</li><li>最大限度地减少程序暂停时间</li></ol><p><strong>❌ 缺点：</strong></p><ol><li><strong>循环引用问题：</strong> 如果两个或多个对象相互引用，它们的引用计数永远不会变为 0，即使它们已经不再被程序访问，也不会被回收，从而导致内存泄漏。</li><li><strong>计数器更新开销：</strong> 在引用计数中，每当对象被引用或取消引用时，都需要更新计数器。这个开销会影响性能，特别是在存在大量对象的情况下。</li><li><strong>不可达对象问题：</strong> 引用计数无法处理循环引用之外的其他类型的不可达对象。例如，如果有一个对象 A 引用了 B，而 B 又引用了 C，但 C 不再被任何其他对象引用，那么 C 将无法被回收。</li></ol><p>由于以上问题，现代的 JavaScript 引擎通常不再采用纯粹的引用计数作为主要的垃圾回收机制。</p><h3 id="标记清除" tabindex="-1">标记清除 <a class="header-anchor" href="#标记清除" aria-label="Permalink to &quot;标记清除&quot;">​</a></h3><p>标记清除（Mark and Sweep）是 JavaScript 中最常见的垃圾回收机制之一。它是一种用于自动内存管理的算法，用于检测和释放不再使用的对象，以避免内存泄漏和内存溢出。<br><strong>✴️ 基本思想：</strong></p><ol><li><strong>标记阶段：</strong> 垃圾回收器从根对象（通常是全局对象、活动执行栈和闭包等）出发，遍历所有可访问的对象，并标记为活动对象。在这个阶段，垃圾回收器会识别出所有被引用的对象，将其标记为“存活”。</li><li><strong>清除阶段：</strong> 在标记阶段完成后，垃圾回收器会对堆内存进行扫描，清除所有未标记的对象，这些对象被认为是“垃圾”，因为它们不再被任何活动对象引用。清除阶段会释放这些垃圾对象所占用的内存空间，使其可用于未来的对象分配。</li></ol><p>标记清除算法通过这两个阶段实现垃圾对象的回收。在标记阶段，垃圾回收器会确定哪些对象仍然处于活动状态。在清除阶段，垃圾回收器会清理所有未被标记的对象，释放内存空间。<br><strong>✅ 优点：</strong></p><ol><li>标记和清除两个阶段执行效率较高</li><li>不需要额外的内存开销</li><li>可以立即回收可回收对象的内存</li></ol><p><strong>❌ 缺点：</strong></p><ol><li>会产生内存碎片,降低内存利用率</li><li>需要暂停程序执行进行完整垃圾回收,可能造成较长的停顿时间</li><li>清除时需要遍历所有对象,比较低效</li><li>标记和清除效率依赖于对象数量,对象越多越慢</li><li>不易实现增量式垃圾回收</li></ol><h3 id="标记整理" tabindex="-1">标记整理 <a class="header-anchor" href="#标记整理" aria-label="Permalink to &quot;标记整理&quot;">​</a></h3><p>标记整理(Mark-and-Compact)是在基本标记清除算法基础上的改进。<br><strong>✴️ 基本思想:</strong></p><ol><li><strong>标记阶段：</strong> 同标记清除一样,首先标记所有正在被引用的对象。</li><li><strong>整理阶段：</strong> 与直接清除不同,标记整理会先执行一次内存整理。将存活对象向内存空间一端移动,然后直接清理掉端边界以外的内存。</li><li><strong>清除阶段：</strong> 空间端边界以外的内存就全部可以直接回收掉了。</li></ol><p><strong>✅ 优点:</strong></p><ol><li>减少内存碎片,内存利用率高</li><li>不需要按顺序回收,回收速度快</li><li>新的对象分配速度也较快</li></ol><p><strong>❌ 缺点：</strong> 存活对象移动需要额外时间与计算资源。标记整理对标记清除进行了改进和优化,应用更加广泛。</p><h3 id="分代回收" tabindex="-1">分代回收 <a class="header-anchor" href="#分代回收" aria-label="Permalink to &quot;分代回收&quot;">​</a></h3><p>分代回收(Generational Garbage Collection)是 JS 垃圾回收机制中的重要优化，是现代 JavaScript 引擎中采用的一种高效垃圾回收策略，它可以显著提高应用的性能和内存管理效率<br><strong>✴️ 基本思想：</strong><br>将内存中的对象分为新生代和老生代,根据对象的生命周期不同进行不同策略的回收。在分代回收的策略中，新创建的对象首先分配到新生代。垃圾回收器在新生代执行频繁的小规模垃圾回收，通常采用快速而简单的算法（比如 Scavenge 算法）来清理不再使用的对象。当对象在新生代经历了一定次数的垃圾回收仍然存活时，它们将被晋升到老生代。老生代的垃圾回收较为复杂，可能会涉及更多的算法和更大的回收范围。<br><strong>✅ 优点：</strong><br>通过区分不同对象的生命周期，它可以更精确地选择垃圾回收的时机和策略。大多数对象在创建后很快就变得不可访问，因此将它们分配到新生代，并频繁进行小规模的垃圾回收，可以有效地释放短期存活对象的内存。而那些长期存活的对象，由于它们在老生代，可能需要较长时间才会进行垃圾回收，从而避免频繁地进行大规模回收，提高了性能。<br><strong>❌ 缺点:</strong></p><ol><li><strong>实现复杂度高：</strong> 分代回收需要维护对象年龄和代的信息,不同代采用不同算法,实现比较复杂。</li><li><strong>内存开销大：</strong> 记录额外的代信息需要占用内存资源。</li><li><strong>参数依赖性强：</strong> 分代大小、对象晋升年龄等参数的设置对效果有很大影响。</li><li><strong>问题未完全解决：</strong> 分代回收只是缓解了频繁回收问题,对象生命周期不固定,仍需全堆回收。</li><li><strong>会产生内存碎片：</strong> 分代独立会导致新生代频繁回收产生大量碎片。</li></ol><h3 id="空闲时垃圾回收" tabindex="-1">空闲时垃圾回收 <a class="header-anchor" href="#空闲时垃圾回收" aria-label="Permalink to &quot;空闲时垃圾回收&quot;">​</a></h3><p>空闲时垃圾回收(Idle-time Garbage Collection)是 JS 垃圾回收机制的一种常见优化技术，用于在系统空闲或闲置时进行垃圾回收，以减少对应用性能的影响。这种技术旨在在用户不活跃或浏览器空闲时，利用系统资源进行垃圾回收，而不会对正在运行的应用产生明显的影响。<br>✴️ <strong>基本思想：</strong></p><ol><li>JS 引擎监测代码执行情况,判断程序何时进入空闲状态。</li><li>在代码空闲执行期间启动垃圾回收,利用 CPU 空闲资源。</li><li>代码执行需要 CPU 时暂停垃圾回收,切换资源服务代码运行。</li><li>交替进行回收和执行,将回收工作分散到不同空隙中。</li></ol><p><strong>✅ 优点：</strong></p><ol><li>减少垃圾回收过程对代码执行流程的影响和干扰。</li><li>避免垃圾回收时产生长时间的执行停顿。</li><li>提高用户体验,减少垃圾回收造成的卡顿感。</li></ol><p>❌ <strong>缺点：</strong> 空闲时垃圾回收并不意味着永远不会有任何垃圾回收暂停。在某些情况下，垃圾回收器可能仍需要在运行时进行一些必要的回收操作。空闲时垃圾回收只是在合适的时机尽量减少对应用的影响。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>垃圾回收是 JS 自动内存管理非常重要的一部分,可以自动回收不再需要的内存对象,防止内存泄漏。主要的垃圾回收算法包括标记清除,标记整理,引用计数等。现代浏览器一般 combine 多个算法来实现。为了优化效率,会使用分代回收适当区分新生和老生对象,以及闲时回收利用 CPU 空闲资源。垃圾回收会有一定的性能影响,我们应该编写高质量代码来配合,减少不必要的内存占用。<br>总的来说,垃圾回收机制使得 JS 开发人员不再需要关注内存控制这块复杂的工作。它极大地简化了 JS 的内存管理,使开发人员可以专注于业务代码的实现。这是 JS 作为一门优秀动态语言的重要支撑。</p>',40)]))}const m=a(e,[["render",n]]);export{b as __pageData,m as default};
